102	   * @deprecated
103	   */
104	  private void readObject(java.io.ObjectInputStream in) throws IOException, ClassNotFoundException {
105	    in.defaultReadObject();
106	  }
107	
108	  @Override
109	  public Option<byte[]> getInstantDetails(HoodieInstant instant) {
110	    return Option.ofNullable(readCommits.get(instant.requestedTime()));
111	  }
112	
113	  @Override
114	  public InputStream getContentStream(HoodieInstant instant) {
115	    return new ByteArrayInputStream(getInstantDetails(instant).orElseGet(() -> new byte[0]));
